#!/usr/bin/env python3
import hashlib,json,re,subprocess,sys
from pathlib import Path
assert sys.flags.isolated and sys.flags.no_site
root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign15-seed-iff-check';draft=root/'research/nine-sharing-sign15-seed-iff-draft';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();r=p/'run.py';m=p/'source-manifest.json';assert sha(r)=='cb9d45935179ba9cb4be6e35ed493cfffb2d51aa04075d27b104981974515d8f' and sha(m)=='20ce7cc16d4c64a1f3536070cd1ea926116e9b40ebd27bb536474c03baec6d0f';row,=json.loads(m.read_text())['rows'];name='Sign15SeedExistential';src=p/'src/DiophantineConsistency'/(name+'.lean');s=src.read_text();assert sha(src)==sha(draft/(name+'.lean'))==row['source_sha256'] and row['module']=='DiophantineConsistency.'+name and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.Sign15ReverseBridge','DiophantineConsistency.Sign15InnerLift','DiophantineConsistency.Sign15SignedValue'];assert not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit)\b',s)
for t in ('theorem exists_same_input','(hb : 0 < beta) (hMC : MC < beta) (hMF : MF < 2 * beta)','v 0 = x ∧ InternalZero (SharingSeed15Degree124.seed p) v','v 0 = x ∧ InternalZero (SharingSeed16Degree112.seed p) v','Sign15InnerLift.exists_inner_of_seed','Sign15ScalarWindow.q_bound_of_seed','Sign15SignedValue.inner_eval','Sign15ZeroBridge.forward','Sign15ZeroBridge.backward'):assert t in s
assert all('(hp'+i+' : ((p '+i+' : ℤ) : DiffRing V) = ι ' in s for i in ('0','1','2','3'))
survey=p/'provider-survey.py';assert sha(survey)=='3eb8ff5ebd9cf828583aab182d016b1c177984be8f156fa6c72dee80b424fc49';runner=r.read_text();assert "'-M2800'" in runner and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in runner and "if local in survey['producers']:" in runner and "for rel,rec in survey['extra'].items():" in runner
for label,pin in [('zero-assembly','0f055f99485e8aa3cf1cec7be3d35ecd0ee849a8cf990ac4eba9a0f3c00f4e76'),('inner-lift','63d18f772d80f1cffceee7a59f21e219dfcd870de9eff44f2720096d77bbbd9a'),('signed-value','ff073372d83ed764e26b506fdfadb5294756ee9e0ec6fff43720ddb7b85935d5')]:
 c=root/('reviews/nine-sharing-sign15-'+label+'-terminal-independent/check.py');assert sha(c)==pin;subprocess.run([sys.executable,'-I','-S','-B',str(c)],capture_output=True,check=True,timeout=120)
z=subprocess.run([sys.executable,'-I','-S','-B',str(survey)],capture_output=True,text=True,check=True,timeout=180);data=json.loads(z.stdout);assert data['status']=='PASS' and len(data['extra'])==130 and len(data['producers'])==2
x=subprocess.run([sys.executable,'-I','-S','-B',str(r),'--preflight'],capture_output=True,text=True,timeout=180);assert x.returncode==0 and not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','extra_overlays':130,'scope':'same-input existential iff proposal under represented ports and bounds; no endpoint or file binding'},indent=2))
